listData:
{{
  (() => {
    const poolData = Array.isArray(Get_Achats_Pool.data) ? Get_Achats_Pool.data : [];
    const fournisseursData = Array.isArray(Get_Fournisseurs_Achats.data) ? [...Get_Fournisseurs_Achats.data] : [];
    const currentTab = appsmith.store.tab_achats || 'A_COMMANDER';

    // 1. Calcul de la date de référence par fournisseur
    const dateRefParFournisseur = {};

    poolData.forEach(row => {
      const idF = row.ID_Fournisseur || 'DIVERS';
      const statut = (row.Statut_Achat || '').toUpperCase();

      let dateLigne = null;
      if (currentTab === 'A_COMMANDER' && ['À COMMANDER', 'A COMMANDER'].includes(statut)) {
        dateLigne = row.Date_Demande;
      } else if (currentTab === 'EN_COMMANDE' && ['COMMANDÉ', 'COMMANDE', 'REÇU PARTIEL', 'RECU PARTIEL'].includes(statut)) {
        dateLigne = row.Date_Commande || row.Date_Demande;
      } else if (currentTab === 'HISTORIQUE' && ['REÇU', 'RECU'].includes(statut)) {
        dateLigne = row.Date_Reception || row.Date_Commande || row.Date_Demande;
      }

      if (dateLigne) {
        const timestampLigne = new Date(dateLigne).getTime();
        if (currentTab === 'HISTORIQUE') {
          // Sur l'historique : date la plus récente
          if (!dateRefParFournisseur[idF] || timestampLigne > dateRefParFournisseur[idF]) {
            dateRefParFournisseur[idF] = timestampLigne;
          }
        } else {
          // Sur A_COMMANDER / EN_COMMANDE : date la plus ancienne
          if (!dateRefParFournisseur[idF] || timestampLigne < dateRefParFournisseur[idF]) {
            dateRefParFournisseur[idF] = timestampLigne;
          }
        }
      }
    });

    // 2. Tri des fournisseurs selon l'onglet
    fournisseursData.sort((a, b) => {
      const idA = a.ID_Fournisseur || 'DIVERS';
      const idB = b.ID_Fournisseur || 'DIVERS';

      if (currentTab === 'HISTORIQUE') {
        const timeA = dateRefParFournisseur[idA] || 0;
        const timeB = dateRefParFournisseur[idB] || 0;
        return timeB - timeA; // Plus récent en premier
      } else {
        const timeA = dateRefParFournisseur[idA] || Infinity;
        const timeB = dateRefParFournisseur[idB] || Infinity;
        return timeA - timeB; // Plus ancien en premier
      }
    });

    // 3. Carte "Tous les fournisseurs" (conservée en 1ère position)
    const totalNbLignes = fournisseursData.reduce((sum, f) => sum + Number(f.Nb_Lignes || f.Nb_Articles || 0), 0);
    const totalHT = fournisseursData.reduce((sum, f) => sum + Number(f.Total_HT || 0), 0);

    const carteTous = {
      ID_Fournisseur: 'TOUS',
      Nom_Fournisseur: 'Tous les fournisseurs',
      Nb_Lignes: totalNbLignes,
      Total_HT: totalHT,
      Franco_De_Port: 0
    };

    return [carteTous, ...fournisseursData];
  })()
}}
